/*----------------------------------------------------------------------------*/

/*  Para escribir cada número (del 0 al 9), se configura el ODR en 0 para encender el segmento y en 1 para apagar.
    gfedcba 
    1000000, // 0
    1111001, // 1
    0100100, // 2
    0110000, // 3
    0011001, // 4
    0010010, // 5
    0000010, // 6
    1111000, // 7
    0000000, // 8
    0010000  // 9
*/

/*
 segmentos del display |GPIO 
a                      |PA11
b                      |PC5
c                      |PC11
d                      |PC12
e                      |PC10
f                      |PA12
g                      |PD2
*/

#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

//-----------------Definición de variables----------------------------------
volatile uint16_t contador = 0; // variable que cambia con las interrupciones
uint8_t refrescar = 0;          // bandera para indicar que se debe refrescar la pantalla con la interrupción del TIM3
uint16_t digito1 = 0;           // dígito de las unidades de mil
uint16_t digito2 = 0;           // dígito de las centenas
uint16_t digito3 = 0;           // dígito de las decenas
uint16_t digito4 = 0;           // dígito de las unidades
uint8_t numero_a_dibujar = 0;   // Variable para almacenar el número a dibujar (solo es una cifra)

//-----------------Definición de funciones----------------------------------
void init_gpio(void);
void init_timers(void);
void init_EXTI(void);

void update_display(void);
void draw_number(void);
void split_number(uint16_t contador, uint8_t cifras[4]);

typedef enum {
    Unidades,
    Decenas,
    Centenas,
    Millares
} DigitoMostrar;
DigitoMostrar digito = Unidades; // Variable para almacenar el dígito actual a mostrar

//--------------------------main-----------------------------------
int main(void)
{
    init_gpio();
    init_timers();
    init_EXTI();

    while(1) {
        if (refrescar) {
            refrescar = 0;      // Limpiar la bandera de refresco
            update_display();   // Actualizar la pantalla de 7 segmentos
        }

    }
    return 0;
}

/**********************************************************************/
//  Configuración  de los periféricos GPIO, TIM2, TIM3 y EXTI
/*********************************************************************/

void init_gpio(void){

    /*********************************************************************/
    //     Habilitar el reloj para los puertos GPIO (A, C, D y H)
    /*********************************************************************/

    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIOCEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOHEN); // Limpiar los bits de habilitación del reloj para GPIOA, GPIOB, GPIOC y GPIOH
    RCC ->AHB1ENR |= RCC_AHB1ENR_GPIOAEN; // Habilitar el reloj para GPIOA
    RCC ->AHB1ENR |= RCC_AHB1ENR_GPIOCEN; // Habilitar el reloj para GPIOC
    RCC ->AHB1ENR |= RCC_AHB1ENR_GPIODEN; // Habilitar el reloj para GPIOD
    RCC ->AHB1ENR |= RCC_AHB1ENR_GPIOHEN; // Habilitar el reloj para GPIOH
    

    /*********************************************************************/
    //      Configurando los pines de salida para los GPIO
    /*********************************************************************/

    // Configurando GPIOC - para cada dígito (transistor pnp) del display de ánodo común:
    // Pin 2, Pin 6, Pin 8, Pin 13

    GPIOC->MODER    &= ~(GPIO_MODER_MODE2 | GPIO_MODER_MODE6 | GPIO_MODER_MODE8 | GPIO_MODER_MODE13);                  // Limpiar el modo de los pines PC2, PC6, PC8 y PC13
    GPIOC->MODER    |= (GPIO_MODER_MODE2_0 | GPIO_MODER_MODE6_0 | GPIO_MODER_MODE8_0 | GPIO_MODER_MODE13_0);           // Configurar PC2, PC6, PC8 y PC13 como salidas
    GPIOC->OTYPER   &= ~(GPIO_OTYPER_OT2 | GPIO_OTYPER_OT6 | GPIO_OTYPER_OT8 | GPIO_OTYPER_OT13);                      // Configurar PC2, PC6, PC8 y PC13 como salida push-pull
    GPIOC->OSPEEDR  &= ~(GPIO_OSPEEDR_OSPEED2 | GPIO_OSPEEDR_OSPEED6 | GPIO_OSPEEDR_OSPEED8 | GPIO_OSPEEDR_OSPEED13);  // Configurar PC2, PC6, PC8 y PC13 como salida de baja velocidad
    GPIOC->PUPDR    &= ~(GPIO_PUPDR_PUPD2 | GPIO_PUPDR_PUPD6 | GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD13);                  // Sin pull up ni pull down
    GPIOC->ODR      &= ~(GPIO_ODR_OD2 | GPIO_ODR_OD6 | GPIO_ODR_OD8 | GPIO_ODR_OD13);                                  // Inicializar los pines PC2, PC6, PC8 y PC13 en 0 logico (encendido el display)
    
    /*********************************************************************/ 

    // Configurando GPIOA0 y GPIOC3 (fotocompuertas):
    // Pin 5, Pin 10
    
    GPIOA->MODER    &= ~(GPIO_MODER_MODE0);   // Entrada
    GPIOA->PUPDR    &= ~(GPIO_PUPDR_PUPD0);   // Limpiar la resistencia de pull up--pull down

    GPIOC->MODER    &= ~(GPIO_MODER_MODE3);   //  Entrada
    GPIOC->PUPDR    &= ~(GPIO_PUPDR_PUPD3);   //  Limpiar la resistencia de pull up--pull down

    /*********************************************************************/ 

    // Configurando los 7 segmentos:

    /* 
    GPIOA: pines 11, 12.
    GPIOC: pines 5, 10, 11, 12. 
    GPIOD: pin 2. 
    */
    GPIOA->MODER &= ~(GPIO_MODER_MODE11 | GPIO_MODER_MODE12);  // Limpiar el modo de los pines PA11 y PA12
    GPIOA->MODER |= (GPIO_MODER_MODE11_0 | GPIO_MODER_MODE12_0); // Configurar PA11 y PA12 como salidas
    GPIOC->MODER &= ~(GPIO_MODER_MODE5 | GPIO_MODER_MODE10 | GPIO_MODER_MODE11 | GPIO_MODER_MODE12); // Limpiar el modo de los pines PC5, PC10, PC11 y PC12
    GPIOC->MODER |= (GPIO_MODER_MODE5_0 | GPIO_MODER_MODE10_0 | GPIO_MODER_MODE11_0 | GPIO_MODER_MODE12_0); // Configurar PC5, PC10, PC11 y PC12 como salidas
    GPIOD->MODER &= ~(GPIO_MODER_MODE2); // Limpiar el modo del pin PD2
    GPIOD->MODER |= (GPIO_MODER_MODE2_0); //  PD2 como salida

    GPIOA->OTYPER  &= ~(GPIO_OTYPER_OT11 | GPIO_OTYPER_OT12); // Configurar PA11 y PA12 como salida push-pull
    GPIOC->OTYPER  &= ~(GPIO_OTYPER_OT5 | GPIO_OTYPER_OT10 | GPIO_OTYPER_OT11 | GPIO_OTYPER_OT12); // Configurar PC5, PC10, PC11 y PC12 como salida push-pull
    GPIOD->OTYPER  &= ~(GPIO_OTYPER_OT2); // Configurar PD2 como salida push-pull
    
    GPIOA->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED11 | GPIO_OSPEEDR_OSPEED12); // Configurar PA11 y PA12 como salida de baja velocidad
    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED5 | GPIO_OSPEEDR_OSPEED10 | GPIO_OSPEEDR_OSPEED11 | GPIO_OSPEEDR_OSPEED12); // Configurar PC5, PC10, PC11 y PC12 como salida de baja velocidad
    GPIOD->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED2); // Configurar PD2 como salida de baja velocidad

    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD11 | GPIO_PUPDR_PUPD12); // Limpiar la resistencia de pull-up/pull-down del pin PA11 y PA12
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD5 | GPIO_PUPDR_PUPD10 | GPIO_PUPDR_PUPD11 | GPIO_PUPDR_PUPD12); // Limpiar la resistencia de pull-up/pull-down del pin PC5, PC10, PC11 y PC12
    GPIOD->PUPDR &= ~(GPIO_PUPDR_PUPD2); // Limpiar la resistencia de pull-up/pull-down del pin PD2

    GPIOA->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12); // Inicializar los pines PA11 y PA12 en 0 LOGICO (led encendido)
    GPIOC->ODR &= ~(GPIO_ODR_OD5 | GPIO_ODR_OD10 | GPIO_ODR_OD11 | GPIO_ODR_OD12); // Inicializar los pines PC5, PC10, PC11 y PC12 en 0 LOGICO (led encendido)
    GPIOD->ODR &= ~(GPIO_ODR_OD2); // Inicializar el pin PD2 en 0 LOGICO (led encendido)

    /***************************************************************************/

    // Configurando GPIOH - pin 1 LED blinky, breadboard

    GPIOH->MODER    &= ~(GPIO_MODER_MODE1);     //Limpiar MODER              
    GPIOH->MODER    |= (GPIO_MODER_MODE1_0);    //Configurar PH0 como salida  
    GPIOH->OTYPER   &= ~(GPIO_OTYPER_OT1);      // Salida push-pull                              
    GPIOH->OSPEEDR  &= ~(GPIO_OSPEEDR_OSPEED1);   // velocidad baja                             
    GPIOH->PUPDR    &= ~(GPIO_PUPDR_PUPD1);       // sin resisencia pull-up y sin resistencia pull-down                               
    GPIOH->ODR      &= ~(GPIO_ODR_OD1);  // Inicializar el pin PH1 en 0 logico (led apagado)                                    
}



void init_timers(void){

    // Habilitar el reloj para TIM2 y TIM3. TIM 2 --> Blinky, TIM3 contador de 7 segmentos
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM2EN | RCC_APB1ENR_TIM3EN); // Limpiar los bits de RCC para TIM2 y TIM3
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN_Msk; // Habilitar señal de reloj para TIM2
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN_Msk; // Habilitar señal de reloj para TIM3

    TIM2->CNT = 0; // Inicializar el contador de TIM2 en 0
    TIM3->CNT = 0; // Inicializar el contador de TIM3 en 0

    TIM2->PSC = 1600 - 1; // Configurar el prescaler de TIM2  (16 MHz / 16000 = 1 kHz --> 1 ms por tick)
    TIM3->PSC = 1600 - 1; // Configurar el prescaler de TIM3  (16 MHz / 16000 = 1 kHz --> 1 ms por tick)

    TIM2->ARR = 2500 - 1; // Configurar el auto-reload de TIM2 para que genere una interrupción cada 2500 ms (2.5 s)
    TIM3->ARR = 15 - 1; // Configurar el auto-reload de TIM3 para que genere una interrupción cada 15 ms
    //TIM3->ARR = 200 - 1; // Configurar el auto-reload de TIM3 para que genere una interrupción cada 200 ms (prueba de refresco del display)
    TIM2->CR1 &= ~(TIM_CR1_CKD); // 00 en el registro CKD; se cuenta con la señal de 16 MHz)
    TIM3->CR1 &= ~(TIM_CR1_CKD); 

    TIM2->CR1 |= (TIM_CR1_ARPE); // Habilitar la precarga del auto-reload para TIM2
    TIM3->CR1 |= (TIM_CR1_ARPE);  // Habilitar la precarga del auto-reload para TIM3

    TIM2->CR1 &= ~(TIM_CR1_DIR); // Configurar TIM2 Conteo ascendente
    TIM3->CR1 &= ~(TIM_CR1_DIR); // Configurar TIM3 Conteo ascendente

    TIM2->DIER |= TIM_DIER_UIE; // Habilitar update interrupt (interrupción por desbordamiento) para TIM2
    TIM3->DIER |= TIM_DIER_UIE; // Habilitar update interrupt para TIM3

    NVIC_EnableIRQ(TIM2_IRQn); // Matricular la interrupción de TIM2 en el NVIC
    NVIC_EnableIRQ(TIM3_IRQn); // Matricular la interrupción de TIM3 en el NVIC

    TIM2->CR1 |= TIM_CR1_CEN; // Habilitar el contador de TIM2
    TIM3->CR1 |= TIM_CR1_CEN; // Habilitar el contador de TIM3

}

/**************************************************************************
            Handlers de interrupción para TIM2 y TIM3
**************************************************************************/

/* Handler para la interrupción de TIM2 */
void TIM2_IRQHandler(void){
    if (TIM2->SR & TIM_SR_UIF) { // Verifica que la interrupción fue por actualización
        TIM2->SR &= ~TIM_SR_UIF; // Limpiar la bandera de interrupción
        GPIOH->ODR ^= GPIO_ODR_OD1; // Alternar el estado (ON/OFF) del blinky
    }
}

/* Handler para la interrupción de TIM3 */
void TIM3_IRQHandler(void){
    if (TIM3->SR & TIM_SR_UIF) { // Verifica que la interrupción fue por actualización
        TIM3->SR &= ~TIM_SR_UIF; // Limpiar la bandera de interrupción
        refrescar = 1; // 'bandera' de refresco display
    }
}

/*********************************************************************/
// Configurando EXTI para los pines PC3 y PA0 (fotocompuertas)
/*********************************************************************/


void init_EXTI(void){

    RCC->APB2ENR &= ~(RCC_APB2ENR_SYSCFGEN); // Deshabilitar el reloj para SYSCFG
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; // Habilitar el reloj para SYSCFG

    SYSCFG->EXTICR[0] &= ~SYSCFG_EXTICR1_EXTI3; // Limpiar
    SYSCFG->EXTICR[0] |= SYSCFG_EXTICR1_EXTI3_PC; // Se utilizará EXTI0 del puerto C (PC3)

    SYSCFG->EXTICR[0] &= ~SYSCFG_EXTICR1_EXTI0; // Limpiar
    SYSCFG->EXTICR[0] |= SYSCFG_EXTICR1_EXTI0_PA; // La línea EXTI3 viene del puerto A (PA0)

    EXTI->RTSR |= EXTI_RTSR_TR3; // interrupción por flanco de subida (cuando ingresa el objeto)
    EXTI->FTSR &= ~EXTI_FTSR_TR3; // interrupción por flanco de bajada desactivado

    EXTI->RTSR &= ~EXTI_RTSR_TR0; // interrupción por flanco de subida desactivado
    EXTI->FTSR |= EXTI_FTSR_TR0; // interrupción por flanco de bajada (cuando sale el objeto)

    EXTI->PR = EXTI_PR_PR3; // Limpiar la bandera (se limpia escribiendo 1)
    EXTI->IMR |= EXTI_IMR_MR3; // 'Desenmascarar'  EXTI3 (habilitar la interrupción, la señal se propaga al NVIC)

    EXTI->PR = EXTI_PR_PR0; // Limpiar la bandera pendiente (se limpia escribiendo 1)
    EXTI->IMR |= EXTI_IMR_MR0; // 'Desenmascarar' EXTI0 (habilitar la interrupción)

    __NVIC_EnableIRQ(EXTI0_IRQn);   // Habilitar en el NVIC la interrupción proveniente de EXTI0 (PA0)
    __NVIC_EnableIRQ(EXTI3_IRQn); // Habilitar en el NVIC la interrupción proveniente de EXTI3 (PC3)

}

/**********************************************************************
                            Handlers EXTI
**********************************************************************/
void EXTI0_IRQHandler(void){
    if (EXTI->PR & EXTI_PR_PR0) { // Verificar si PA0 generó la interrupción
        EXTI->PR |= EXTI_PR_PR0; // Limpiar la bandera pendiente (escribiendo 1)

        contador--; //  el contador disminuyendo en 1
    }
}

void EXTI3_IRQHandler(void){
    if (EXTI->PR & EXTI_PR_PR3) { // Verificar si PA3 generó la interrupción
        EXTI->PR |= EXTI_PR_PR3; // Limpiar la bandera pendiente (escribiendo 1)
        contador++; //  el contador aumenta en 1
    }
}


/*********************************************************************/
/*                              LÓGICA                              */
/*******************************************************************/

/*********************************************************************/
// Actualización del display
/*********************************************************************/

void update_display(void){
    /*--- Dividir el número en unidades, decenas, centenas y unidades de mil ---*/
    digito1 = (contador / 1000) % 10; // Dígito de las unidades de mil
    digito2 = (contador / 100) % 10;  // Dígito de las centenas
    digito3 = (contador / 10) % 10;   // Dígito de las decenas
    digito4 = contador % 10;          // Dígito de las unidades

    // Lógica para actualizar la pantalla:
    switch (digito) {
        case Unidades:
            GPIOC->ODR  |= (GPIO_ODR_OD2 | GPIO_ODR_OD6 | GPIO_ODR_OD8 | GPIO_ODR_OD13); // 1 en la base, apaga los digitos (transistores)
            numero_a_dibujar = digito4; // Mostrar el dígito de las unidades
            draw_number(); // Dibujar el número en la pantalla de 7 segmentos
            GPIOC->ODR  &= ~(GPIO_ODR_OD13); // 0 en la base, enciende el dígito de las unidades
            digito = Decenas; // Pasar al siguiente dígito
            break;
        case Decenas:
            GPIOC->ODR  |= (GPIO_ODR_OD2 | GPIO_ODR_OD6 | GPIO_ODR_OD8 | GPIO_ODR_OD13); // 1 en la base, apaga los digitos (transistores)
            numero_a_dibujar = digito3; // Mostrar el dígito de las decenas
            draw_number(); // Dibujar el número en la pantalla de 7 segmentos
            GPIOC->ODR  &= ~(GPIO_ODR_OD8); // 0 en la base, enciende el dígito de las unidades
            digito = Centenas; // Pasar al siguiente dígito
            break;
        case Centenas:
            GPIOC->ODR  |= (GPIO_ODR_OD2 | GPIO_ODR_OD6 | GPIO_ODR_OD8 | GPIO_ODR_OD13); // 1 en la base, apaga los digitos (transistores)
            numero_a_dibujar = digito2; // Mostrar el dígito de las centenas
            draw_number(); // Dibujar el número en la pantalla de 7 segmentos
            GPIOC->ODR  &= ~(GPIO_ODR_OD2); // 0 en la base, enciende el dígito de las centenas
            digito = Millares; // Pasar al siguiente dígito
            break;
        case Millares:
            GPIOC->ODR  |= (GPIO_ODR_OD2 | GPIO_ODR_OD6 | GPIO_ODR_OD8 | GPIO_ODR_OD13); // 1 en la base, apaga los digitos (transistores)
            numero_a_dibujar = digito1; // Mostrar el dígito de las unidades de mil
            draw_number(); // Dibujar el número en la pantalla de 7 segmentos
            GPIOC->ODR  &= ~(GPIO_ODR_OD6); // 0 en la base, enciende el dígito de las unidades de mil
            digito = Unidades; // Pasar al siguiente dígito
            break;
        default:
            // Manejo de error: dígito no válido
            break;
    
    }
}

/*********************************************************************
                            Dibujar número
*********************************************************************/
void draw_number(void){
    switch (numero_a_dibujar) {
        case 0:
            GPIOA->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12);                                // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~(GPIO_ODR_OD5 | GPIO_ODR_OD10 | GPIO_ODR_OD11 | GPIO_ODR_OD12); // 0 LOGICO (led encendido)
        
            GPIOD->ODR |= (GPIO_ODR_OD2);                                                  // 1 LOGICO (led apagado)
            break;
        case 1:
            GPIOC->ODR &= ~(GPIO_ODR_OD5 | GPIO_ODR_OD11); // 0 LOGICO (led encendido)

            GPIOA->ODR |= (GPIO_ODR_OD11 | GPIO_ODR_OD12); // 1 LOGICO (led apagado)
            GPIOC->ODR |= (GPIO_ODR_OD10 | GPIO_ODR_OD12); // 1 LOGICO (led apagado)
            GPIOD->ODR |= (GPIO_ODR_OD2);                  // 1 LOGICO (led apagado)

            break;
        case 2:
            // Lógica para dibujar el número 2
            GPIOA->ODR &= ~(GPIO_ODR_OD11);                                // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~(GPIO_ODR_OD5 | GPIO_ODR_OD10 | GPIO_ODR_OD12); // 0 LOGICO (led encendido)
            GPIOD->ODR &=  ~(GPIO_ODR_OD2);                                // 0 LOGICO (led encendido)

            GPIOA->ODR |=  (GPIO_ODR_OD12);
            GPIOC->ODR |=  (GPIO_ODR_OD11);
            break;
        case 3:
            // Lógica para dibujar el número 3
            GPIOA->ODR &= ~(GPIO_ODR_OD11);                                // 0 LOGICO (led encendido)
            GPIOA->ODR |=  (GPIO_ODR_OD12);
            GPIOC->ODR &= ~(GPIO_ODR_OD5 | GPIO_ODR_OD11 | GPIO_ODR_OD12); // 0 LOGICO (led encendido)
            GPIOC->ODR |=  (GPIO_ODR_OD10);
            GPIOD->ODR &=  ~(GPIO_ODR_OD2);
            break;
        case 4:
            // Lógica para dibujar el número 4
            GPIOA->ODR |=  (GPIO_ODR_OD11);                  // 1 LOGICO (led apagado)
            GPIOA->ODR &= ~(GPIO_ODR_OD12);                 // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~(GPIO_ODR_OD5 | GPIO_ODR_OD11); // 0 LOGICO (led encendido)
            GPIOC->ODR |=  (GPIO_ODR_OD10 | GPIO_ODR_OD12);
            GPIOD->ODR &=  ~(GPIO_ODR_OD2);
            break;
        case 5:
            GPIOA->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12);    // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12);   // 0 LOGICO (led encendido)
            GPIOC->ODR |=  (GPIO_ODR_OD5 | GPIO_ODR_OD10);   // 1 LOGICO (led apagado)
            GPIOD->ODR &=  ~(GPIO_ODR_OD2);                 // 1 LOGICO (led apagado)

            break;
        case 6:
            GPIOA->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12); // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~( GPIO_ODR_OD5 | GPIO_ODR_OD10 | GPIO_ODR_OD11 | GPIO_ODR_OD12); // 0 LOGICO (led encendido)
            GPIOD->ODR &= ~(GPIO_ODR_OD2 ); // 0 LOGICO (led encendido)

            GPIOC->ODR |= (GPIO_ODR_OD5); // 1 LOGICO (led apagado)

            break;
        case 7:
            GPIOA->ODR &= ~(GPIO_ODR_OD11);                 // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~( GPIO_ODR_OD5 | GPIO_ODR_OD11); // 0 LOGICO (led encendido)

            GPIOA->ODR|= (GPIO_ODR_OD12);                   // 1 LOGICO (led apagado)
            GPIOC->ODR|= (GPIO_ODR_OD10 |GPIO_ODR_OD12);
            GPIOD->ODR |=  (GPIO_ODR_OD2); 
            break;
        case 8:
            GPIOA->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12); 
            GPIOC->ODR &= ~( GPIO_ODR_OD10 | GPIO_ODR_OD11 | GPIO_ODR_OD12); 
            GPIOC->ODR &= ~(GPIO_ODR_OD5 ); 
            GPIOD->ODR &= ~(GPIO_ODR_OD2); 
            break;
        case 9:
            GPIOA->ODR &= ~(GPIO_ODR_OD11 | GPIO_ODR_OD12);                                  // 0 LOGICO (led encendido)
            GPIOC->ODR &= ~( GPIO_ODR_OD5|GPIO_ODR_OD10 | GPIO_ODR_OD11 | GPIO_ODR_OD12);   // 0 LOGICO (led encendido)
            GPIOD->ODR &= ~(GPIO_ODR_OD2);                                                 // 0 LOGICO (led encendido)

            GPIOC->ODR |= (GPIO_ODR_OD10); // 1 LOGICO (led apagado)
            break;
        default:
            // Manejo de error: número no válido
            break;
    
    }
}